// https://docs.expo.dev/guides/using-eslint/
const { defineConfig } = require('eslint/config');
const expoConfig = require('eslint-config-expo/flat');

module.exports = defineConfig([
  {
    // `.expo/` is generated by expo-router (typed routes) and gitignored, so
    // linting it only ever produces a complaint about a file nobody can edit.
    ignores: ['dist/*', '.expo/*'],
  },
  expoConfig,
  {
    // The icon generator is a plain Node script, not app code, so it runs
    // against Node's globals rather than React Native's. Without this, every
    // use of `Buffer` is an error — thirteen of them, which is enough noise to
    // hide a real one.
    files: ['scripts/**/*.mjs'],
    languageOptions: {
      globals: { Buffer: 'readonly', process: 'readonly', console: 'readonly' },
    },
  },
  {
    // Vendored verbatim from the web app, with a `@parity exact` hash that
    // `npm run parity` checks. `array-type` is stylistic, so satisfying it here
    // would mean editing files whose whole point is that they are byte-identical
    // to their source — breaking the contract to tidy a type annotation.
    files: ['src/domain/**/*.ts'],
    rules: { '@typescript-eslint/array-type': 'off' },
  },
]);
